-- Extend the existing public rendering allowlists for new cosmetic styles.
-- Keep the function's privacy checks, earned entitlements and execution privileges.
do $wardrobe$
declare
  previous_catalog constant text := $old_catalog$v_catalog constant jsonb := '{"mode":[["picture",0],["built",0]],"skin":[["sand",0],["peach",0],["honey",0],["cocoa",0],["umber",0],["ebony",0]],"hair":[["sweep",0],["curls",0],["bob",0],["crop",0],["bald",0],["ponytail",0],["waves",0],["braids",0]],"hairColor":[["brown",0],["black",0],["blond",0],["auburn",0],["silver",0]],"shirt":[["navy",0],["green",0],["orange",0],["blue",0],["berry",0]],"background":[["lilac",0],["sky",0],["sage",0],["sunshine",0],["coral",0]],"glasses":[["none",0],["round",150],["square",600],["sun",1000],["monocle",2250],["heart",2750],["star",3500],["visor",5000],["doughnut",6500],["camera",8250],["academy_mathspecs",0],["discovery_gameface",0],["days_sunday",0]],"hat":[["none",0],["pumpkin-thinker",-1],["beanie",500],["egg",1200],["cap",1500],["corn",2200],["toast",2800],["cloud",4000],["coffee",4750],["wave",5500],["wizard",6000],["graduate",8000],["academy_calendar",0],["academy_detective",0],["academy_rainbow",0],["discovery_paperhat",0],["discovery_crunch",0],["days_daydreamer",0]],"prop":[["none",0],["little-bat",-1],["cookie",300],["icepop",800],["peas",1800],["bulb",2500],["train",3200],["owl",3800],["pencil",4500],["nacho",5750],["rocket",7000],["roll",7500],["book",9000],["academy_abacus",0],["academy_moon",0],["academy_pie",0],["academy_puzzle",0],["discovery_trailmix",0],["discovery_globe",0],["days_thyme",0],["days_smore",0]],"frame":[["level",0],["midnight",-1],["blue",100],["green",500],["copper",1500],["prism",2500],["gold",3000],["aurora",4750],["orbit",6000],["nova",8500]]}'::jsonb;$old_catalog$;
  expanded_catalog constant text := $new_catalog$v_catalog constant jsonb := '{"mode":[["picture",0],["built",0]],"skin":[["sand",0],["peach",0],["honey",0],["cocoa",0],["umber",0],["ebony",0],["porcelain",0],["rose-beige",0],["almond",0],["olive",0],["toffee",0],["walnut",0],["espresso",0]],"hair":[["sweep",0],["curls",0],["bob",0],["crop",0],["bald",0],["ponytail",0],["waves",0],["braids",0],["pixie",0],["locs",0],["buns",0],["undercut",0],["fro",0],["quiff",0],["pigtails",0],["mohawk",0],["antenna",0]],"hairColor":[["brown",0],["black",0],["blond",0],["auburn",0],["silver",0],["chestnut",0],["ginger",0],["platinum",0],["plum",0],["lagoon",0],["lavender",0],["rose",0],["copper-sun",0],["ink-tide",0],["berry-frost",0],["comet-white",0],["afterglow",0]],"shirt":[["navy",0],["green",0],["orange",0],["blue",0],["berry",0],["cream",0],["burgundy",0],["charcoal",0],["mint",0],["yellow",0],["lavender",0],["varsity",0],["reef",0],["orchid",0],["eclipse",0],["sherbet",0]],"background":[["lilac",0],["sky",0],["sage",0],["sunshine",0],["coral",0]],"glasses":[["none",0],["round",150],["square",600],["sun",1000],["monocle",2250],["heart",2750],["star",3500],["visor",5000],["doughnut",6500],["camera",8250],["academy_mathspecs",0],["discovery_gameface",0],["days_sunday",0],["aviator",450],["butterfly",1650],["spectrum",4200]],"hat":[["none",0],["pumpkin-thinker",-1],["beanie",500],["egg",1200],["cap",1500],["corn",2200],["toast",2800],["cloud",4000],["coffee",4750],["wave",5500],["wizard",6000],["graduate",8000],["academy_calendar",0],["academy_detective",0],["academy_rainbow",0],["discovery_paperhat",0],["discovery_crunch",0],["days_daydreamer",0],["bucket",950],["jelly",3300],["astral",7200]],"prop":[["none",0],["little-bat",-1],["cookie",300],["icepop",800],["peas",1800],["bulb",2500],["train",3200],["owl",3800],["pencil",4500],["nacho",5750],["rocket",7000],["roll",7500],["book",9000],["academy_abacus",0],["academy_moon",0],["academy_pie",0],["academy_puzzle",0],["discovery_trailmix",0],["discovery_globe",0],["days_thyme",0],["days_smore",0],["headphones",650],["sprout",1450],["scarf",2850],["drone",5200]],"frame":[["level",0],["midnight",-1],["blue",100],["green",500],["copper",1500],["prism",2500],["gold",3000],["aurora",4750],["orbit",6000],["nova",8500]]}'::jsonb;$new_catalog$;
  previous_titles constant text := $old_titles$v_titles constant jsonb := '[["none",0],["explorer",250],["curious",750],["detective",2000],["thinker",4500],["sage",10000]]'::jsonb;$old_titles$;
  expanded_titles constant text := $new_titles$v_titles constant jsonb := '[["none",0],["explorer",250],["trail",425],["curious",750],["sparks",1350],["detective",2000],["maker",3250],["thinker",4500],["afterdark",5600],["polymath",7800],["sage",10000]]'::jsonb;$new_titles$;
  definition text := pg_catalog.pg_get_functiondef('brainilab_private.player_avatar(uuid)'::regprocedure);
  original_digest constant text := 'e47cc52c95dcc53a7b7bc86514f66c8f';
  updated text;
begin
  if pg_catalog.md5(pg_catalog.replace(pg_catalog.replace(definition, expanded_catalog, previous_catalog), expanded_titles, previous_titles))
      <> original_digest then
    raise exception 'Avatar function definition changed; inspect the deployed version before extending the wardrobe';
  end if;
  if pg_catalog.strpos(definition, expanded_catalog) > 0 and pg_catalog.strpos(definition, expanded_titles) > 0 then
    return;
  end if;
  updated := pg_catalog.replace(pg_catalog.replace(definition, previous_catalog, expanded_catalog), previous_titles, expanded_titles);
  if pg_catalog.strpos(updated, expanded_catalog) = 0 or pg_catalog.strpos(updated, expanded_titles) = 0 then
    raise exception 'Avatar catalogue update is incomplete';
  end if;
  execute updated;
end;
$wardrobe$;
